    options: ['TRUE', 'FALSE'],
    correctAnswer: 0,
    hint: 'In operant conditioning, negative means removing or withholding, and punishment means decreasing behavior.',
    explanation: 'True. In operant conditioning, negative punishment (punishment by removal) involves removing or taking away a pleasant or desirable stimulus following an undesirable behavior in order to decrease or suppress the future occurrence of that behavior.',
