    difficulty: 'medium',
    topic: 'Classical Conditioning Principles',
    points: 10,
    question: '[Part II: Matching - Item 2] Match the description with the correct classical conditioning principle from Column B:\n\n"Occurred when conditioned stimulus repeatedly presented without presenting unconditioned stimulus."',
