    explanation: 'Option D (Extinction) is correct. Extinction is the gradual weakening and eventual disappearance of a conditioned response (CR) when the conditioned stimulus (CS) is repeatedly presented alone without the unconditioned stimulus (UCS).',
    explanationAmharic: 'መልስ D (Extinction - መጥፋት/መዳከም)። የተለማመዱት ማነቃቂያ (ለምሳሌ የደወል ድምፅ) ያለ ተፈጥሯዊው ማነቃቂያ (ያለ ምግብ) በተደጋጋሚ ሲቀርብ፣ የተማሩት ምላሽ ቀስ በቀስ እየደበዘዘና እየጠፋ ሲሄድ Extinction ይባላል።',
    explanationAfaanOromo: 'Deebiin D (Extinction) dha. Qaqqabsiisaan barame (CS) osoo qaqqabsiisaan uumamaa (UCS) hin dhiyaatin yeroo hedduu irra deddeebi\'amee yeroo dhiyaatu, deebiin barame suuta suutaan bada.'
