    explanationAfaanOromo: 'Tiyooriin kufee baduu (Decay Theory) odeeffannoon tokko yeroo dheeraaf yoo hin irra deebi\'amne fi hin hojiirra hin oolle, faanti yaadannoo sammuu keessaa suuta suutaan baduu akka danda\'u ibsa. Kanaaf deebiin C dha.'
