    explanation: 'Implicit (procedural / non-declarative) memory is a subsystem of long-term memory responsible for knowing "how" to do things—motor skills, learned automatic habits, and conditioned reflexes (e.g., riding a bike, typing) executed without conscious awareness. Option A is correct.',
    explanationAmharic: 'የተግባር/የክህሎት ማህደረ-ትውስታ (Implicit ወይም Procedural memory) ክህሎቶችን፣ ልምዶችን እና አካላዊ ድርጊቶችን (ለምሳሌ ብስክሌት መንዳት ወይም በኮምፒውተር መተየብ) በንዑስ-አእምሮ በማስቀመጥ ያለብዙ ንቁ ጥረት እንድንከውን የሚያስችለን የረጅም ጊዜ ማህደረ-ትውስታ ንዑስ ክፍል ነው። ስለዚህ ትክክለኛው መልስ A ነው።',
    explanationAfaanOromo: 'Yaadannoo dandeettii fi amalaa (Implicit / Procedural memory) dandeettii hojii fi shaakalaa (fkn biskileetii oofuu, kiiboordii rukutuu) kan sammuun ofumaan yaadatu dha. Deebiin A dha.'
