    explanationAfaanOromo: 'Ilaalcha Namummaa (Humanistic perspective - D): Addummaa, cimina dhuunfaa fi dandeettii guutuu (full potential) namaa irratti kan xiyyeeffatu dha. Deebiin D dha.'
