    explanationAmharic: 'ተለዋዋጭ ክፍለ-ጊዜ (Variable interval - A)፡- ድንገተኛ እና ያልተጠበቀ ጉርሻ ባልታወቀና በማይታወቅ የጊዜ ርዝማኔ ውስጥ ሲሰጥ Variable Interval ይባላል። መልሱ A ነው።',
