    points: 10,
    question: 'Assume that the son has always gotten a candy when he buys a mobile card to his father Desta; however, the son does not thinks to get candy from anyone other than his father while he is sent to buy mobile card; Thus, which principles of classical conditioning is best represented in the above given scenario?',
