    explanationAmharic: 'ማነቃቂያን መለየት (Stimulus discrimination - C)፡- ልጁ ከሌሎች ሰዎች ጋር ሳይሆን ከአባቱ ብቻ ከረሜላ እንደሚጠብቅ መለየቱና ምላሽ መስጠቱ በክላሲካል ኮንዲሽኒንግ ማነቃቂያን መለየት (Discrimination) ይባላል። መልሱ C ነው።',
    explanationAfaanOromo: 'Kakaastuu adda baafachuu (Stimulus discrimination - C): Ilmi sun abbaa isaa qofa irraa loozensii eeguu fi namoota biraa irraa eeguu dhiisuun dandeettii kakaastuu adda baasuu agarsiisa. Deebiin C dha.'
