    explanationAfaanOromo: 'Jajjabina Pozatiivii (Positive Reinforcement - A): Hojii gaarii hojjetaniif wanta gaarii (bonasii mindaa ji\'a tokkoo) dabalataan kennuun fakkeenya Positive Reinforcement dha. Deebiin A dha.'
