    explanationAfaanOromo: 'Fixed Interval (C): Jajjabinni ykn badhaasni yeroo murtaa\'aa qofa eeggatee (waggaa waggaan) waan kennamuuf Fixed Interval jedhama. Deebiin C dha.'
