    explanationAfaanOromo: 'Deebiin sirriin C dha: Yaadannoo yeroo gabaabaa \'working memory\' kan jedhameef odeeffannoo yaadannoo yeroo dheeraa irraa dhufe qindeessee fi itti dhimma bahee waan hojjetuufi.'
