    explanationAmharic: 'የኋሊት ጣልቃ-ገብነት (Retroactive interference - C)፡- ከሰአት በኋላ አዲስ የተማረው ትምህርት (Critical thinking)፣ ጠዋት አስቀድሞ የተማረውን የስነ-ልቦና ትምህርት (Psychology) እንዳያስታውስ ሲያስተጓጉልበት Retroactive interference ይባላል። መልሱ C ነው።',
    explanationAfaanOromo: 'Retroactive interference (C): Wanti haaraa galgala baratame (Critical thinking) wanta duraan ganama baratame (Psychology) akka hin yaadatamin yoo dhorku Retroactive interference jedhama. Deebiin C dha.'
