    explanation: 'Option A is correct.\nBy the fundamental equivalence law of material implication, the conditional statement (p => q) is logically equivalent to (~p ∨ q).\n\nBecause both expressions have identical truth tables across all 4 truth assignments of p and q:\n- When both sides evaluate to True, True <=> True is True.\n- When both sides evaluate to False, False <=> False is True.\n\nSince the biconditional is True for every possible assignment of truth values, it is a Tautology.'
