    explanation: 'Option C is correct.\nLet n be the number of elements in the set.\n- The total number of subsets in the power set is 2^n.\n- Proper subsets exclude the set itself, giving 2^n - 1 proper subsets.\n- Non-empty proper subsets exclude both the set itself and the empty set ∅, giving 2^n - 2 non-empty proper subsets.\n\nWe are given that the number of non-empty proper subsets is 2:\n2^n - 2 = 2\n2^n = 4\n2^n = 2^2\nn = 2\n\nVerification: Let S = {a, b} (where n = 2).\n- All subsets: ∅, {a}, {b}, {a, b} (total 4 subsets).\n- Proper subsets: ∅, {a}, {b} (total 3 subsets).\n- Non-empty proper subsets: {a}, {b} (exactly 2 subsets).\n\nThus, the set must contain 2 elements.'
