    explanation: 'Answer: lub = 1 and glb = -1/3.\n\nStep 1: Compute the terms of the set A for natural numbers n = 1, 2, 3, 4, ...:\nGeneral term formula: a_n = (-1)^n / (1 - 2n)\n\n- For n = 1:\na_1 = (-1)^1 / (1 - 2(1)) = -1 / (1 - 2) = -1 / -1 = 1\n\n- For n = 2:\na_2 = (-1)^2 / (1 - 2(2)) = 1 / (1 - 4) = 1 / -3 = -1/3\n\n- For n = 3:\na_3 = (-1)^3 / (1 - 2(3)) = -1 / (1 - 6) = -1 / -5 = 1/5\n\n- For n = 4:\na_4 = (-1)^4 / (1 - 2(4)) = 1 / (1 - 8) = 1 / -7 = -1/7\n\n- For n = 5:\na_5 = (-1)^5 / (1 - 2(5)) = -1 / (1 - 10) = -1 / -9 = 1/9\n\n- For n = 6:\na_6 = (-1)^6 / (1 - 2(6)) = 1 / (1 - 12) = 1 / -11 = -1/11\n\nStep 2: Analyze the positive terms (odd values of n):\nPositive terms: { 1, 1/5, 1/9, 1/13, ... }\nThese terms strictly decrease as n increases, with the maximum value occurring at n = 1:\nMaximum = 1.\nSince 1 is in the set and every element in A is <= 1, the least upper bound (lub / supremum) is 1.\n\nStep 3: Analyze the negative terms (even values of n):\nNegative terms: { -1/3, -1/7, -1/11, -1/15, ... }\nAs n increases, 1/(2n - 1) approaches 0, so -1/(2n - 1) strictly increases towards 0.\nThe smallest (most negative) value occurs at n = 2:\nMinimum = -1/3.\nSince -1/3 is in the set and every element in A is >= -1/3, the greatest lower bound (glb / infimum) is -1/3.\n\nTherefore, lub = 1 and glb = -1/3.'
