    explanation: 'Option C (Subclass definition). A definition by subclass assigns meaning to a term by naming subclasses (species or subsets) of the class denoted by the term. "Tigers", "panthers", "lions", and "cougars" are subclasses of the larger class "feline". (Enumerative definitions identify individual named members, e.g., "Simba", while subclass definitions name entire categories).',
    explanationAmharic: 'ንዑስ-ዝርያዎችን በመዘርዘር የሚሰጥ ፍቺ (Subclass definition - መልስ C)፡- አንድን ሰፊ ቃል (feline) በስሩ የሚገኙ ንዑስ ቡድኖችን ወይም ዝርያዎችን (ነብር፣ አንበሳ፣ አቦሸማኔ፣ የቤት ድመት) በመጥቀስ ትርጉም ሲሰጥ Subclass definition ይባላል። ስለዚህ መልሱ C ነው።',
    explanationAfaanOromo: 'Hiika gartuu xiqqaa dhiyeessuu (Subclass definition - Deebii C): Jecha garee bal\'aa ta\'e (feline) sanyiiwwan ykn gartuuwwan isaa gadii (qeerrensa, leenca, adurree) maqaa dhahuun ibsuu dha. Deebiin C dha.'
