    explanationAmharic: 'እብድ / Crazy (መልስ B)፡- "Crazy" የሚለው ቃል በሁለት የተለያዩ ትርጉሞች በመዋሉ አሻሚ (ambiguous) ሆኗል። በመጀመሪያው አረፍተ ነገር ላይ ሰውን ለማሳቅ የሚደረግ አስቂኝ ወይም ግልፍተኛ ባህሪን የሚያመለክት ሲሆን፣ ቀጥሎ ግን የአእምሮ በሽተኛ ተደርጎ ተተርጉሟል።',
