    explanationAfaanOromo: 'Dhugaa (True): Falaasamni akka qorannoo qeeqaatti (critical enterprise) sammuun gad-fageenyaan yaaduu (reflective) fi sababaan xiinxaluu (rational thinking) wajjin wal-qabata. Kanaaf dhugaa dha.'
