    explanationAfaanOromo: 'Deebii D (Neutralize): Jechi "Neutralize" jedhu jecha miiraa (emotive term) yoo ta\'u, ajjeechaa ykn dhabamsiisuu karaa miira dhoksuun ibsuuf kan fayyadame dha.'
