    topic: 'Meaning: Vagueness in Verbal Disputes',
    points: 10,
    question: 'Zenebe: Tomorrow I\'m going to the Metallica concert. Their music is fabulous. Ahmed: You call that music? Really it\'s just noise, and incredibly loud noise at that. Which word in this verbal dispute is vague?',
