    correctAnswer: 2,
    hint: 'The disagreement hinges on the fuzzy, indefinite borderline separating organized sound ("music") from acoustic clatter ("noise").',
    explanation: 'Option C (Music). The verbal dispute arises from the vagueness of "music". A term is vague if there are borderline cases where it is impossible to determine whether the term applies. Zenebe and Ahmed disagree because the criteria distinguishing music from sheer noise are ambiguous and imprecise in this context.',
    explanationAmharic: 'መልስ C (Music / ሙዚቃ)። በዚህ የቃላት ክርክር ውስጥ ዝናቡና አህመድ የተጋጩት "ሙዚቃ (Music)" የሚለው ቃል ድንበሩ ግልጽ ባለመሆኑ (Vague) ነው። የትኛው ድምጽ እንደ ሙዚቃ ይቆጠራል ወይስ እንደ ጩኸት በሚለው የትርጉም ወሰን ላይ የተመሰረተ ነው።',
    explanationAfaanOromo: 'Deebii C (Music): Falmiin kun jecha "Music" jedhu irratti kan uumame yoo ta\'u, daangaan muuziqaa fi sagalee jeequmsaa (noise) gidduu jiru ifa waan hin taaneef (vague) wal-dhabani.'
