    explanationAmharic: 'መልስ A (Paleozoic Era)። በፓሊዮዞይክ ዘመን ኢትዮጵያ ከፍተኛ የየብስ አካል ስለነበረች ለረጅም ጊዜያት የማያቋርጥ መሸርሸር (denudation and peneplanation) ተካሂዶባታል እንጂ ምንም ዓይነት አዲስ አለት አልተፈጠረባትም።',
    explanationAfaanOromo: 'Deebiin A (Paleozoic Era) dha. Bara Paaloyoozoyikii keessa naannoon Itoophiyaa lafa olka\'aa waan tureef dhiqama dheeraa (denudation) keessa darbe malee gosti dhagaa haaraan hin uumamne.'
