    explanationAfaanOromo: 'Deebiin A (Southeast lowlands). Dhagoonni kutaalee bishaanii durii (Mesozoic marine sediments) lafa dachee Kibba-Bahaa (Ogaadeen) keessatti lafa irratti bal\'inaan mul\'atu.'
