    explanationAmharic: 'መልስ B (Fluvial deposits - የወንዝ ደለል ክምችት)። በወንዞች ዳርቻ፣ በጎርፍ ሜዳዎችና በተፋሰሶች ላይ በፈሳሽ ወንዞች ተጠርጎ የሚቀመጥ ደለል "Fluvial deposit" (የወንዝ ደለል) ይባላል።',
    explanationAfaanOromo: 'Deebiin B (Fluvial deposits). Cobsii ykn dhangala\'aa bishaanii fi laggeeniin dhiibamee qarqara laggeenii fi dirreewwan bishaanii irratti kuufamu "Fluvial deposits" jedhama.'
