    explanationAmharic: 'መልስ A። የኢትዮጵያ ደጋማ ስፍራዎች በሞቃትና ተስማሚ አየር ንብረት፣ አስተማማኝ ዝናብ፣ ከሞቃታማ በሽታዎች (እንደ ወባ) ነፃ በመሆናቸው ጥቅጥቅ ያለ ህዝብ እና ቋሚ የግብርና ስራ (sedentary economic activity) ይካሄድባቸዋል።',
