    explanationAmharic: 'መልስ B (The Shewa Plateau - የሸዋ አምባ)። የሸዋ አምባ (Shewa Plateau) በምዕራባዊ ደጋዎች ውስጥ እጅግ ሰፊና ጠፍጣፋ አናት (extensive flat-topped uplands) ያለው አምባ ሲሆን፣ የአባይ፣ አዋሽና ኦሞ ወንዞች መነሻ ሆኖ ያገለግላል።',
    explanationAfaanOromo: 'Deebiin B (The Shewa Plateau). Dirreen Shawaa (Shewa Plateau) dacheewwan olka\'oo dhihaa keessatti lafa bal\'aa fi gubbaan isaa diriiraa ta\'e kan qabu yoo ta\'u, madda laggeen Abbaayyaa, Awaash fi Oomooti.'
