    explanation: 'Option A is correct. As answered on the official university exam key: Advantages of large size include: 1) Large area of arable land and diverse natural/mineral/water resources; 2) Greater strategic depth in defense against external invasion; 3) Diverse agro-climatic zones and cultures. Disadvantages of large size include: 1) Huge financial capital required to construct and maintain infrastructure (roads, schools, electricity, healthcare); 2) High difficulty in socio-economic integration and central administrative governance; 3) Long international borders vulnerable to smuggling, conflict, and defense burdens.',
    explanationAmharic: 'መልስ A። የኢትዮጵያ ስፋት የሚያስገኛቸው ጥቅሞች፡ 1) ሰፊ ሊታረስ የሚችል መሬትና የተፈጥሮ ሀብት ብዝሃነት፣ 2) በውጭ ወረራ ጊዜ ጥልቅ የመከላከያ ምሽግ (strategic depth) መፍጠሩ። ጉዳቶች፡ 1) የመሰረተ ልማት ዝርጋታ (መንገድ፣ መብራት፣ ባቡር) እጅግ ከፍተኛ ወጪ የሚጠይቅ መሆኑ፣ 2) ሰፊ ድንበሮችን ለመጠበቅና ሀገራዊ አስተዳደርን ለማስተሳሰር ፈታኝ መሆኑ።',
