    explanation: 'False. Massive salt deposits (halite and potash evaporites) characterize the Afar (Danakil) Depression, which lies below sea level in an extremely hyper-arid basin. In contrast, the Chew Bahir Rift (Southern Rift) is a shallow, marshy alluvial depression filled with sediments brought down by the Segen River.',
