    explanationAmharic: 'መልስ A (Longitude / Meridians - የኬንትሮስ መስመሮች)። ከሰሜን ወደ ደቡብ ተዘርግተው የምስራቅ ወይም የምዕራብን አቅጣጫ መገኛ የሚያሳዩ ምናባዊ መስመሮች የኬንትሮስ መስመሮች (Longitudes/Meridians) ይባላሉ።',
    explanationAfaanOromo: 'Deebiin A (Longitude / Meridians - Sararoota Dheerinaa) dha. Sararoonni yaadaa kaabaa gara kibbaatti diriiruun fageenya gara bahaa ykn dhihaa agarsiisan Sarara Dheerinaa (Longitudes) jedhamu.'
