    explanationAfaanOromo: 'Deebiin A (The Main Ethiopian Rift - Sulula Raaftii Giddu-galeessaa) dha. Kutaa Sulula Raaftii keessaa kan haroowwan hedduu, margaa fi qilleensa mijataa qabaachuun uummata baay\'een qabame Main Ethiopian Rift jedhama.'
