    explanationAmharic: 'መልስ A (Radiometric dating / የራዲዮአክቲቭ የዕድሜ መለኪያ ዘዴ)። የአዕድንትና የአለቶችን ትክክለኛ የዓመታት ዕድሜ (numerical age) ለመወሰን እጅግ አስተማማኙ ሳይንሳዊ ዘዴ ራዲዮሜትሪክ ዴቲንግ (Radiometric dating / Potassium-Argon) ነው።',
    explanationAfaanOromo: 'Deebiin A (Radiometric dating / Teknika Raadiyoo-meetirii) dha. Umurii sirrii albuudotaa fi dhagootaa lakkoofsaan adda baasuuf mala hunda caalaa amansiisaan tekniika raadiyoo-aktiviitii fayyadamuuni.'
