    explanationAfaanOromo: 'Deebiin A dha. Bakki sirriin (absolute location) sarara laatitiiwudii fi loongiitiiwudiitiin qofa ibsama. Kanneen hafan hundi bakka wal-bira qabamee ilaalamu (relative location) dha.'
