    explanationAmharic: 'መልስ A (Rainfed-agriculture - በዝናብ የሚካሄድ ግብርና)። የአፋር ትሪያንግል እጅግ ሞቃታማና ደረቅ በመሆኑ በዝናብ የሚካሄድ ግብርና ፈጽሞ አይታሰብም። በምትኩ በመስኖ፣ በጨው ማውጣትና በጂኦተርማል ሀይል ይታወቃል።',
