    explanationAmharic: 'መልስ A (Slow rising and sinking of the land)። መሬት በዝግታ ወደ ታች መስመጥና ወደ ላይ መነሳት የተከሰተው በሜሶዞይክ ዘመን የባህር መግባትና መውጣትን ያስከተለው ሂደት ነው። ፕሪካምብሪያን ግን የተራሮች መፈጠርና የመሰረት ድንጋይ (basement complex) የተፈጠረበት ነበር።',
