    explanationAmharic: 'መልስ B። ሒንታሎ የኖራ ድንጋይ (Hintalo limestone) የተፈጠረው ባህሩ ከፍተኛ ጥልቀት ላይ በደረሰበት ወቅት (deep marine transgression) እንጂ ባህሩ ሲሸሽ (regression) አይደለም። ባህሩ ሲሸሽ የተፈጠረው የላይኛው አሸዋማ ድንጋይ (Upper sandstone) ነው።',
    explanationAfaanOromo: 'Deebiin B dha. Dhagaan sokorruu Hintaloo (Hintalo limestone) kan uumame yeroo galaanni gara lafaatti gadi-fageenyaan seene (transgression) keessa malee yeroo galaanni baqatee duubatti deebi\'e (regression) miti.'
