    explanationAmharic: 'መልስ C። አፍሪካ ከደቡብ አሜሪካ የተለየችው በጥንታዊው የሜሶዞይክ ዘመን የጎንድዋናላንድ መከፋፈል ወቅት እንጂ በቅርቡ በተፈጠረው የስምጥ ሸለቆ እንቅስቃሴ አይደለም። ሌሎች አማራጮች ግን የስምጥ ሸለቆው ውጤቶች ናቸው።',
