    explanation: 'Step 1: The work done by a constant force acting at an angle theta to the displacement vector is W = F · d · cos(theta).\nStep 2: Substitute F = 50 N, d = 20 m, and theta = 60°:\nW = 50 · 20 · cos(60°) = 1000 · 0.5 = 500 Joules. Option B is correct.'
