    explanation: 'Step 1: Convert distances to meters:\nd1 = 160 km = 160,000 m\nd2 = 160 km = 160,000 m\nTotal distance D = 160,000 + 160,000 = 320,000 m.\nStep 2: Calculate elapsed time for each leg of the journey:\nt1 = d1 / v1 = 160,000 m / 80 m/s = 2000 s\nt2 = d2 / v2 = 160,000 m / 100 m/s = 1600 s\nTotal time T = t1 + t2 = 2000 + 1600 = 3600 s.\nStep 3: Calculate average speed:\nv_avg = Total Distance / Total Time = 320,000 m / 3600 s = 3200 / 36 ≈ 88.89 m/s ≈ 89 m/s.\nOption B is correct.'
