    question: '[Part II: Item 15] A system consists of three particles with masses m₁ = 2.0 kg located at r₁ = 2i m, m₂ = 1.5 kg at r₂ = (-i - j) m, and unknown mass m₃ at unknown location r₃ = x₃ i + y₃ j. If the total mass is M = 5.0 kg and r_cm = (0.8i + 0.3j) m, then find m₃, x₃, and y₃:',
